BEGIN;

DELETE FROM questions WHERE topic = 'Reproduction' AND subtopic IN ('Crossing Over & Recombination', 'Linkage & Independent Assortment', 'Meiosis I vs II & Reductional/Equational Division', 'Nondisjunction & Meiosis vs Mitosis', 'Synapsis, Tetrads & the Synaptonemal Complex');

-- Q1 [Meiosis I vs II & Reductional/Equational Division | easy | Skill 1 | ans A]
WITH q AS (
  INSERT INTO questions (section, topic, subtopic, question_text, options, correct_answer, explanation, difficulty, foundation, content_category, discipline, cognitive_skill, estimated_time_seconds)
  VALUES (
    'bio_biochem', 'Reproduction', $sub1$Meiosis I vs II & Reductional/Equational Division$sub1$, $qt1$A diploid germ cell (2n) completes meiosis I, and a cytologist examines one of the two resulting cells. To explain why meiosis I is classified as the reductional division of meiosis, the cytologist points to the event that lowered the cell's chromosome-set number.$qt1$, $op1$[{"label": "A", "text": "Homologous chromosomes are separated to opposite poles, reducing the chromosome-set number from two (2n) to one (n)."}, {"label": "B", "text": "Sister chromatids are separated to opposite poles, reducing the chromosome-set number from two (2n) to one (n)."}, {"label": "C", "text": "The chromosome-set number stays at two (2n) through meiosis I and is lowered to one (n) only during meiosis II."}, {"label": "D", "text": "Homologous chromosomes are separated to opposite poles, yet the cell stays diploid because each chromosome still holds two sister chromatids."}]$op1$::jsonb, 'A', $ex1$This is a Biology question that falls under the content category 'Meiosis & Genetic Variability (BIO)'. The answer is A because separating homologous chromosomes is the event that drops the ploidy level from two sets to one, which is exactly why meiosis I is named the reductional division. The text states that when the tetrad is broken up and the homologous chromosomes move to opposite poles, "the ploidy level—the number of sets of chromosomes in each future nucleus—has been reduced from two to one. For this reason, meiosis I is referred to as a reductional division." Each resulting cell is haploid because "at each pole, there is just one of each pair of the homologous chromosomes," so only one full set is present. The fact that each chromosome still consists of two sister chromatids does not change the set count, because ploidy is defined by the number of chromosome sets, not the amount of DNA. (Choice A) is correct: the homologs separating in anaphase I is precisely the event that halves the chromosome-set number from 2n to n. (Choice B) is wrong because sister chromatids do not separate in meiosis I; that separation is the meiosis II event, which is "not a reduction division." (Choice C) misplaces the ploidy drop, since the reduction occurs in meiosis I and meiosis II keeps "still one set of chromosomes, as there was at the end of meiosis I." (Choice D) correctly identifies the homolog-separation event but wrongly concludes the cell stays diploid, conflating the persistence of two sister chromatids with chromosome-set number. This is a Knowledge of Scientific Concepts and Principles question because it asks the student to recall the defining event and definition of the reductional division directly from established meiotic principles.$ex1$, 'easy', '1C', $cc1$Meiosis & Genetic Variability (BIO)$cc1$, 'biology', 1, 75
  ) RETURNING id
)
INSERT INTO question_distractor_metadata (question_id, choice_label, distractor_category, archetype)
SELECT id, 'B', 'reversed_relationship', $a1B$Assigns the meiosis II event (sister-chromatid separation) to meiosis I as the cause of the ploidy reduction.$a1B$ FROM q
UNION ALL SELECT id, 'C', 'misconception', $a1C$Places the diploid-to-haploid ploidy drop in the wrong division, calling meiosis II the reductional step.$a1C$ FROM q
UNION ALL SELECT id, 'D', 'partial_truth', $a1D$Identifies the correct homolog-separation event but conflates DNA/chromatid content with ploidy, wrongly keeping the cell diploid.$a1D$ FROM q;

-- Q2 [Meiosis I vs II & Reductional/Equational Division | easy | Skill 1 | ans B]
WITH q AS (
  INSERT INTO questions (section, topic, subtopic, question_text, options, correct_answer, explanation, difficulty, foundation, content_category, discipline, cognitive_skill, estimated_time_seconds)
  VALUES (
    'bio_biochem', 'Reproduction', $sub2$Meiosis I vs II & Reductional/Equational Division$sub2$, $qt2$A spermatocyte that has already completed meiosis I contains a single set of replicated chromosomes, each still made of two sister chromatids joined at the centromere. As this haploid cell proceeds through meiosis II, the sister chromatids of each chromosome are pulled to opposite poles. A student is asked to predict the effect of meiosis II on the cell's ploidy and to classify the division.$qt2$, $op2$[{"label": "A", "text": "During meiosis II homologous chromosomes separate, lowering the chromosome-set number from two to one, so meiosis II is the reduction division."}, {"label": "B", "text": "During meiosis II sister chromatids separate while the chromosome-set number stays at one, so meiosis II is an equational division, not a reduction division."}, {"label": "C", "text": "During meiosis II sister chromatids separate and the ploidy drops from haploid to a still-lower level, completing a second reduction begun in meiosis I."}, {"label": "D", "text": "During meiosis II the synaptonemal complex re-forms so homologs can cross over a second time before the sister chromatids separate."}]$op2$::jsonb, 'B', $ex2$This is a Biology question that falls under the content category 'Meiosis & Genetic Variability (BIO)'. The answer is B because meiosis II separates the two sister chromatids of each chromosome without removing the single chromosome set the cell already possesses, so ploidy stays at n and the division is equational rather than reductional. The reduction in ploidy from two sets to one occurs earlier, when homologous chromosomes separate in meiosis I: "the ploidy level...has been reduced from two to one. For this reason, meiosis I is referred to as a reductional division." Meiosis II instead resembles mitosis—"During anaphase II, as in mitotic anaphase, the kinetochores divide and one sister chromatid—now referred to as a chromosome—is pulled to one pole while the other sister chromatid is pulled to the other pole"—and the text states plainly that "Meiosis II is not a reduction division because although there are fewer copies of the genome in the resulting cells, there is still one set of chromosomes, as there was at the end of meiosis I." (Choice A) is wrong because homologous chromosomes separate in meiosis I, not meiosis II; assigning the meiosis-I event to meiosis II misidentifies which division is reductional. (Choice B) is correct because separating sister chromatids leaves the single chromosome set intact, keeping the cell haploid and making meiosis II equational. (Choice C) is wrong because no second drop in ploidy occurs—after meiosis II "there is still one set of chromosomes," so the cell does not fall below n. (Choice D) is wrong because the synaptonemal complex forms only during prophase I to mediate crossing over and breaks down before meiosis II, so no new crossover occurs in meiosis II. This is a Knowledge of Scientific Concepts and Principles question because it asks the student to recall the defined distinction between the reductional division (meiosis I) and the equational division (meiosis II) and apply it to a stated cellular event.$ex2$, 'easy', '1C', $cc2$Meiosis & Genetic Variability (BIO)$cc2$, 'biology', 1, 75
  ) RETURNING id
)
INSERT INTO question_distractor_metadata (question_id, choice_label, distractor_category, archetype)
SELECT id, 'A', 'process_step_confusion', $a2A$Assigns the meiosis-I homolog-separation (reductional) event to meiosis II$a2A$ FROM q
UNION ALL SELECT id, 'C', 'misconception', $a2C$Invents a second ploidy reduction in meiosis II that does not occur$a2C$ FROM q
UNION ALL SELECT id, 'D', 'adjacent_fact', $a2D$Misplaces the prophase-I synaptonemal complex / crossing-over event into meiosis II$a2D$ FROM q;

-- Q3 [Meiosis I vs II & Reductional/Equational Division | medium | Skill 2 | ans C]
WITH q AS (
  INSERT INTO questions (section, topic, subtopic, question_text, options, correct_answer, explanation, difficulty, foundation, content_category, discipline, cognitive_skill, estimated_time_seconds)
  VALUES (
    'bio_biochem', 'Reproduction', $sub3$Meiosis I vs II & Reductional/Equational Division$sub3$, $qt3$A spermatocyte completes a single round of DNA replication in S phase and then proceeds through both meiotic divisions to completion without errors. A student is asked to predict the number of cells produced and the chromosomal makeup of each resulting cell relative to the original diploid precursor.$qt3$, $op3$[{"label": "A", "text": "Four diploid cells, because the DNA replicates once before each of the two divisions, so two replications paired with two divisions preserve the diploid number."}, {"label": "B", "text": "Two haploid cells, because the one replication and two divisions yield products that each carry chromosomes still made of two sister chromatids."}, {"label": "C", "text": "Four haploid cells, because the single replication followed by two divisions ends with each cell holding one chromosome set whose chromosomes are now single chromatids."}, {"label": "D", "text": "Four cells with one-quarter the original chromosome number, because each of the two divisions halves the chromosome set, so 2n becomes n/2."}]$op3$::jsonb, 'C', $ex3$This is a Biology question that falls under the content category 'Meiosis & Genetic Variability (BIO)'. The answer is C because meiosis pairs one round of chromosome replication with two rounds of nuclear division, so a single diploid precursor yields four haploid cells whose chromosomes have been resolved into single chromatids by the end of meiosis II. The text states that to halve chromosome number, \"meiosis consists of one round of chromosome replication followed by two rounds of nuclear division,\" and that in meiosis II the \"two sister chromatids will separate, creating four haploid daughter cells.\" The first division reduces ploidy from two sets to one (the reductional division), leaving each cell haploid but with chromosomes still made of two sister chromatids; meiosis II then separates those chromatids, so each final cell ends with \"a single copy of each chromosome.\" Because DNA was copied only once but the cell divided twice, the DNA content is halved at each division relative to that single replication. (Choice A) is wrong because it inserts a second S phase—copying DNA before each division is the mitotic one-replication-per-division pattern, which would keep cells diploid, not the meiotic design. (Choice B) is wrong because it stops counting at the two products of meiosis I, which are indeed haploid with two-chromatid chromosomes, but meiosis II still separates those chromatids to make four cells. (Choice C) is correct because the one-replication, two-division design produces four haploid cells, each with one chromosome set of single-chromatid chromosomes. (Choice D) is wrong because meiosis II is not a second ploidy halving; the text notes meiosis II \"is not a reduction division\" since there is still one chromosome set, so the final cells are n, not n/2. This is a Scientific Reasoning and Problem Solving question because it requires the student to integrate the one-replication/two-division architecture with the reductional-versus-equational distinction to predict both the number and the chromosomal makeup of the gametes.$ex3$, 'medium', '1C', $cc3$Meiosis & Genetic Variability (BIO)$cc3$, 'biology', 2, 105
  ) RETURNING id
)
INSERT INTO question_distractor_metadata (question_id, choice_label, distractor_category, archetype)
SELECT id, 'A', 'misconception', $a3A$Inserts a second S phase, applying the mitotic one-replication-per-division pattern to keep products diploid$a3A$ FROM q
UNION ALL SELECT id, 'B', 'process_step_confusion', $a3B$Stops the count at the meiosis I products (two haploid two-chromatid cells), omitting meiosis II$a3B$ FROM q
UNION ALL SELECT id, 'D', 'scale_unit_error', $a3D$Treats meiosis II as a second ploidy halving, so 2n is wrongly driven to n/2$a3D$ FROM q;

-- Q4 [Meiosis I vs II & Reductional/Equational Division | medium | Skill 2 | ans D]
WITH q AS (
  INSERT INTO questions (section, topic, subtopic, question_text, options, correct_answer, explanation, difficulty, foundation, content_category, discipline, cognitive_skill, estimated_time_seconds)
  VALUES (
    'bio_biochem', 'Reproduction', $sub4$Meiosis I vs II & Reductional/Equational Division$sub4$, $qt4$A cytogeneticist isolates a single daughter cell the instant meiosis I finishes (after telophase I and cytokinesis but before meiosis II begins) from a cell whose diploid number is 2n = 6, and measures both its chromosome set number and the structure of each chromosome. Which result does the cell show at this moment?$qt4$, $op4$[{"label": "A", "text": "The cell is still diploid, and each chromosome is composed of two sister chromatids that will be separated during meiosis II."}, {"label": "B", "text": "The cell is haploid, and each chromosome is already a single chromatid, giving it the same DNA content as a finished gamete."}, {"label": "C", "text": "The cell is haploid, and each chromosome is composed of four chromatids still held together as a tetrad after anaphase I."}, {"label": "D", "text": "The cell is haploid, yet each chromosome is still composed of two sister chromatids that will be separated during meiosis II."}]$op4$::jsonb, 'D', $ex4$This is a Biology question that falls under the content category 'Meiosis & Genetic Variability (BIO)'. The answer is D because at the completion of meiosis I a daughter cell already contains only one set of chromosomes (it is haploid), but each of those chromosomes is still made of two sister chromatids that do not separate until meiosis II. The text states that "Two haploid cells are the result of the first meiotic division of a diploid cell... This is why the cells are considered haploid—there is only one chromosome set, even though each chromosome still consists of two sister chromatids" (lines 13860-13863), and that "In meiosis II, these two sister chromatids will separate, creating four haploid daughter cells" (lines 13864-13865). Thus the reduction in ploidy is already complete, but the DNA per chromosome has not yet halved, so the cell does not yet have a gamete's final DNA content. (Choice A) is wrong because meiosis reduces the starting diploid nucleus to haploid—"the starting nucleus is always diploid and the daughter nuclei that result are haploid" (lines 13673-13674)—so the cell is no longer 2n after meiosis I. (Choice B) is wrong because the sister chromatids do not separate during meiosis I; they "will separate" in meiosis II (lines 13864-13865), so each chromosome is still two chromatids, not one, and the DNA content is not yet that of a finished gamete. (Choice C) is wrong because a tetrad—"a total of four sister chromatids of each pair of homologous chromosomes" (lines 13746-13747)—is a prophase-I structure held together at chiasmata that "are broken in anaphase I as the microtubules... pull the homologous chromosomes apart" (lines 13847-13848), so no four-chromatid unit survives into telophase I. (Choice D) is correct because the cell is haploid yet each chromosome retains its two sister chromatids until they separate in meiosis II. This is a Scientific Reasoning and Problem Solving question because it requires distinguishing ploidy (chromosome-set number) from per-chromosome chromatid/DNA content and predicting the precise structural state of a cell at a defined point in the meiotic sequence.$ex4$, 'medium', '1C', $cc4$Meiosis & Genetic Variability (BIO)$cc4$, 'biology', 2, 110
  ) RETURNING id
)
INSERT INTO question_distractor_metadata (question_id, choice_label, distractor_category, archetype)
SELECT id, 'A', 'misconception', $a4A$Keeps the cell at 2n because two chromatids are visible, conflating chromatid count with ploidy$a4A$ FROM q
UNION ALL SELECT id, 'B', 'partial_truth', $a4B$Correct haploid ploidy but moves sister-chromatid separation one division too early to meiosis I$a4B$ FROM q
UNION ALL SELECT id, 'C', 'process_step_confusion', $a4C$Carries the prophase-I tetrad structure past anaphase I into telophase I$a4C$ FROM q;

-- Q5 [Meiosis I vs II & Reductional/Equational Division | hard | Skill 2 | ans B]
WITH q AS (
  INSERT INTO questions (section, topic, subtopic, question_text, options, correct_answer, explanation, difficulty, foundation, content_category, discipline, cognitive_skill, estimated_time_seconds)
  VALUES (
    'bio_biochem', 'Reproduction', $sub5$Meiosis I vs II & Reductional/Equational Division$sub5$, $qt5$A geneticist tracks a single secondary oocyte through meiosis II and focuses on chromosome 7, a chromosome that experienced no crossover event during the preceding meiosis I. She compares the two cells produced by this one meiosis-II division at a locus on chromosome 7. What is the genetic relationship of the two products at that locus, and why?$qt5$, $op5$[{"label": "A", "text": "They are genetically identical at that locus because a short round of DNA replication during interkinesis copies the chromosome just before the chromatids are pulled apart."}, {"label": "B", "text": "They are genetically identical at that locus because interkinesis adds no new DNA, so meiosis II merely separates the pre-existing sister chromatids of that chromosome."}, {"label": "C", "text": "They are genetically different at that locus because meiosis II, like meiosis I, separates homologous chromosomes that carry different alleles."}, {"label": "D", "text": "They are genetically different at that locus because the chromatids being separated are non-identical recombinant copies, even where no crossover occurred."}]$op5$::jsonb, 'B', $ex5$This is a Biology question that falls under the content category 'Meiosis & Genetic Variability (BIO)'. The answer is B because the absence of an S phase in interkinesis means no new DNA is synthesized before meiosis II, so the division simply pulls apart sister chromatids that already existed, leaving the two products identical at any region not altered by crossover. The text states that "Interkinesis lacks an S phase, so chromosomes are not duplicated" and that during meiosis II "the sister chromatids within the two daughter cells separate." Because sister chromatids are "merely duplicates of one of the two homologous chromosomes (except for changes that occurred during crossing over)," a chromosome that never crossed over carries two identical chromatids, and separating them yields identical products. The text confirms this equational outcome directly: "If it were not for the fact that there had been crossover, the two products of each individual meiosis II division would be identical (as in mitosis)." (Choice A) is wrong because it invents a replication step in interkinesis; the text explicitly says interkinesis "lacks an S phase, so chromosomes are not duplicated," so the correct identical outcome is reached through a false mechanism. (Choice B) is correct because no DNA is added before meiosis II, making the division equational and the non-recombinant products identical. (Choice C) is wrong because homolog separation occurs in meiosis I ("homologous chromosomes separate"), the reductional division, whereas meiosis II separates sister chromatids, not homologs. (Choice D) is wrong because, although crossover does create non-identical chromatids, this difference is confined to the regions that actually crossed over; for a locus on a chromosome with no crossover, the chromatids remain identical. This is a Scientific Reasoning and Problem Solving question because the student must chain the fact that interkinesis lacks an S phase to the equational nature of meiosis II and then apply it to a specific non-recombinant locus to predict the genetic relationship of the products.$ex5$, 'hard', '1C', $cc5$Meiosis & Genetic Variability (BIO)$cc5$, 'biology', 2, 150
  ) RETURNING id
)
INSERT INTO question_distractor_metadata (question_id, choice_label, distractor_category, archetype)
SELECT id, 'A', 'misconception', $a5A$Invents an interkinesis S phase, reaching the correct identical outcome through a fabricated replication step$a5A$ FROM q
UNION ALL SELECT id, 'C', 'reversed_relationship', $a5C$Assigns homolog separation and guaranteed genetic difference to meiosis II instead of meiosis I$a5C$ FROM q
UNION ALL SELECT id, 'D', 'partial_truth', $a5D$Correct that crossover creates differences, but wrongly extends that difference to a region where no crossover occurred$a5D$ FROM q;

-- Q6 [Synapsis, Tetrads & the Synaptonemal Complex | easy | Skill 1 | ans C]
WITH q AS (
  INSERT INTO questions (section, topic, subtopic, question_text, options, correct_answer, explanation, difficulty, foundation, content_category, discipline, cognitive_skill, estimated_time_seconds)
  VALUES (
    'bio_biochem', 'Reproduction', $sub6$Synapsis, Tetrads & the Synaptonemal Complex$sub6$, $qt6$During prophase I of meiosis, a cytologist watching a single cell sees one maternal chromosome and its paternal homolog draw tightly together along their entire length, stabilized by a protein lattice. The paired structure now visible at that site is best identified as:$qt6$, $op6$[{"label": "A", "text": "a dyad of two sister chromatids belonging to one replicated chromosome and joined at the centromere"}, {"label": "B", "text": "a single replicated chromosome made of two chromatids attached to each other at a chiasma"}, {"label": "C", "text": "a tetrad of two homologous chromosomes containing four sister chromatids bound together along their length"}, {"label": "D", "text": "a pair of non-homologous chromosomes aligned at the metaphase plate by kinetochore microtubules"}]$op6$::jsonb, 'C', $ex6$This is a Biology question that falls under the content category 'Meiosis & Genetic Variability (BIO)'. The answer is C because synapsis brings the two duplicated homologous chromosomes (four chromatids total) into tight, lengthwise pairing during prophase I, and this paired structure is called a tetrad. The text states that "the tight pairing of the homologous chromosomes is called synapsis" and that the resulting "pairs are called tetrads because a total of four sister chromatids of each pair of homologous chromosomes are now visible." The glossary reinforces this, defining a tetrad as "two duplicated homologous chromosomes (four chromatids) bound together by chiasmata during prophase I." Because two replicated homologs pair, the structure contains exactly four chromatids, not two. (Choice A) A dyad of two sister chromatids joined at the centromere is a single replicated chromosome (two chromatids), not the four-chromatid pairing produced by synapsis. (Choice B) A single replicated chromosome made of two chromatids is only half of the tetrad; the chiasma is the crossover contact point, but the structure formed by synapsis comprises two homologs, not one chromosome. (Choice C) Correct: synapsis pairs the two homologs to form a tetrad of four sister chromatids held together along their length. (Choice D) Synapsis pairs homologous chromosomes during prophase I, whereas alignment of chromosomes at the metaphase plate by kinetochore microtubules occurs later, at metaphase, and synapsis specifically does not pair non-homologous chromosomes. This is a Knowledge of Scientific Concepts and Principles question because it requires recognizing and naming the standard structure (the tetrad) formed by homologous pairing during prophase I as defined in the text.$ex6$, 'easy', '1C', $cc6$Meiosis & Genetic Variability (BIO)$cc6$, 'biology', 1, 75
  ) RETURNING id
)
INSERT INTO question_distractor_metadata (question_id, choice_label, distractor_category, archetype)
SELECT id, 'A', 'adjacent_fact', $a6A$Names a real meiotic structure (a single replicated chromosome's two sister chromatids) but with the wrong chromatid count and identity$a6A$ FROM q
UNION ALL SELECT id, 'B', 'misconception', $a6B$Confuses the four-chromatid tetrad with one replicated chromosome and misassigns the chiasma as what holds a single chromosome together$a6B$ FROM q
UNION ALL SELECT id, 'D', 'misconception', $a6D$Confuses prophase I synapsis of homologs with metaphase alignment of chromosomes and wrongly pairs non-homologous chromosomes$a6D$ FROM q;

-- Q7 [Synapsis, Tetrads & the Synaptonemal Complex | medium | Skill 2 | ans D]
WITH q AS (
  INSERT INTO questions (section, topic, subtopic, question_text, options, correct_answer, explanation, difficulty, foundation, content_category, discipline, cognitive_skill, estimated_time_seconds)
  VALUES (
    'bio_biochem', 'Reproduction', $sub7$Synapsis, Tetrads & the Synaptonemal Complex$sub7$, $qt7$A geneticist treats spermatocytes with a drug that, during prophase I only, prevents assembly of the protein lattice that normally spreads between paired homologs, while the cohesin holding sister chromatids at their centromeres remains fully functional. Which prophase-I outcome is most directly blocked in the treated cells?$qt7$, $op7$[{"label": "A", "text": "Replication of each chromosome into two identical sister chromatids fails to occur."}, {"label": "B", "text": "Sister chromatids of each chromosome separate from each other prematurely."}, {"label": "C", "text": "The homologous chromosomes are unable to condense into visible structures at all."}, {"label": "D", "text": "Crossing over between nonsister chromatids fails, so no chiasmata form between homologs."}]$op7$::jsonb, 'D', $ex7$This is a Biology question that falls under the content category 'Meiosis & Genetic Variability (BIO)'. The answer is D because the synaptonemal complex is the protein lattice that holds homologous chromosomes in precise alignment and directly supports the reciprocal exchange of segments between nonsister chromatids; abolishing its assembly therefore blocks crossing over and the chiasmata that crossing over produces. The text states that the synaptonemal complex is "a lattice of proteins between the homologous chromosomes" within which "the genes on the chromatids of the homologous chromosomes are aligned precisely," and that it "supports the exchange of chromosomal segments between homologous nonsister chromatids—a process called crossing over... observed visually after the exchange as chiasmata." Because the drug acts only in prophase I and leaves centromeric cohesin intact, the upstream replication step (S phase) and sister-chromatid cohesion are untouched, isolating the loss of crossover/chiasma formation as the most direct downstream effect. (Choice A) is wrong because DNA replication into sister chromatids happens earlier, "During DNA duplication in the S phase," not in prophase I, so the synaptonemal complex never performs replication. (Choice B) is wrong because sister chromatids are held "at the centromere by cohesin proteins, which hold the chromatids together until anaphase II," and the problem specifies cohesin is intact, so premature separation does not occur. (Choice C) is wrong because condensation proceeds independently of the lattice; the text notes that "the synaptonemal complex begins to break down and the chromosomes begin to condense," showing condensation occurs as the complex disassembles rather than requiring it. (Choice D) is correct because the synaptonemal complex is the alignment lattice that supports crossing over, so without it the reciprocal exchange between nonsister chromatids and the resulting chiasmata cannot form. This is a Scientific Reasoning and Problem Solving question because it requires predicting the specific downstream consequence of a targeted molecular perturbation by distinguishing the synaptonemal complex's role from the separately controlled processes of replication, cohesion, and condensation.$ex7$, 'medium', '1C', $cc7$Meiosis & Genetic Variability (BIO)$cc7$, 'biology', 2, 110
  ) RETURNING id
)
INSERT INTO question_distractor_metadata (question_id, choice_label, distractor_category, archetype)
SELECT id, 'A', 'process_step_confusion', $a7A$Attributes an earlier-phase event (S-phase replication) to the perturbed prophase-I structure$a7A$ FROM q
UNION ALL SELECT id, 'B', 'misconception', $a7B$Conflates the synaptonemal-complex lattice with centromeric cohesin proteins$a7B$ FROM q
UNION ALL SELECT id, 'C', 'partial_truth', $a7C$Treats the SC as required for condensation when condensation proceeds independently as the SC breaks down$a7C$ FROM q;

-- Q8 [Synapsis, Tetrads & the Synaptonemal Complex | medium | Skill 2 | ans A]
WITH q AS (
  INSERT INTO questions (section, topic, subtopic, question_text, options, correct_answer, explanation, difficulty, foundation, content_category, discipline, cognitive_skill, estimated_time_seconds)
  VALUES (
    'bio_biochem', 'Reproduction', $sub8$Synapsis, Tetrads & the Synaptonemal Complex$sub8$, $qt8$A cell-biology student examines two cells side by side: one is a somatic cell in mitotic prophase, the other is a germ-line cell in prophase I of meiosis. The student wants to identify the single chromosomal event present in the meiotic cell but absent from the mitotic cell. Which event correctly distinguishes the prophase-I cell?$qt8$, $op8$[{"label": "A", "text": "Homologous chromosomes pair tightly along their full length by synapsis, supported by a synaptonemal complex."}, {"label": "B", "text": "Sister chromatids of each chromosome are held together at the centromere by cohesin proteins."}, {"label": "C", "text": "Chromosomes are attached at their tips to the nuclear envelope by associated proteins."}, {"label": "D", "text": "Spindle microtubules attach to kinetochore proteins so the chromosomes can be pulled apart."}]$op8$::jsonb, 'A', $ex8$This is a Biology question that falls under the content category 'Meiosis & Genetic Variability (BIO)'. The answer is A because synapsis—the tight, full-length pairing of homologous chromosomes mediated by the synaptonemal complex—occurs in prophase I but never in mitotic prophase. The text states that early in prophase I "The synaptonemal complex, a lattice of proteins between the homologous chromosomes, first forms at specific locations and then spreads outward to cover the entire length of the chromosomes. The tight pairing of the homologous chromosomes is called synapsis." Crucially, the same passage notes, "Recall that in mitosis, homologous chromosomes do not pair together," so synapsis is the defining feature that separates the two cells. The other listed events either also occur in mitosis or are not the homolog-pairing event being asked about. (Choice A) is correct: homolog-to-homolog synapsis along the full length is unique to prophase I and is absent from mitosis, where homologs stay independent. (Choice B) is wrong because cohesin holding sister chromatids together at the centromere is real, but sister-chromatid cohesion also occurs in mitosis, so it cannot be the distinguishing event. (Choice C) is wrong because tip attachment to the nuclear envelope, while a genuine prophase-I detail, is not the homolog-pairing event the question targets. (Choice D) is wrong because spindle attachment to kinetochores is the key event of prometaphase, not the synapsis event of prophase I. This is a Scientific Reasoning and Problem Solving question because it requires comparing two cell types and reasoning out which single chromosomal event is uniquely diagnostic of meiotic prophase I rather than simply recalling a definition.$ex8$, 'medium', '1C', $cc8$Meiosis & Genetic Variability (BIO)$cc8$, 'biology', 2, 105
  ) RETURNING id
)
INSERT INTO question_distractor_metadata (question_id, choice_label, distractor_category, archetype)
SELECT id, 'B', 'partial_truth', $a8B$Cites a real cohesin-at-centromere interaction but mislabels a universal mitotic feature as meiosis-specific$a8B$ FROM q
UNION ALL SELECT id, 'C', 'adjacent_fact', $a8C$Names a true prophase-I detail (nuclear-envelope tip attachment) that is not the homolog-pairing event asked about$a8C$ FROM q
