UNION ALL SELECT id, 'C', 'process_step_confusion', $a13C$Mistaking the anaphase I resolution/breaking of chiasmata for the site of the exchange itself$a13C$ FROM q
UNION ALL SELECT id, 'D', 'adjacent_fact', $a13D$Assigning crossing over to prophase II, a true prophase that nonetheless lacks synapsis$a13D$ FROM q;

-- Q14 [Crossing Over & Recombination | hard | Skill 2 | ans C]
WITH q AS (
  INSERT INTO questions (section, topic, subtopic, question_text, options, correct_answer, explanation, difficulty, foundation, content_category, discipline, cognitive_skill, estimated_time_seconds)
  VALUES (
    'bio_biochem', 'Reproduction', $sub14$Crossing Over & Recombination$sub14$, $qt14$A geneticist engineers a diploid organism in which a single forced crossover is fully suppressed, so that no chiasmata form and no crossing over occurs anywhere during prophase I, yet meiosis otherwise proceeds normally through both divisions. The organism predicts the consequence for the genetic variability of the resulting gametes.$qt14$, $op14$[{"label": "A", "text": "All genetic variation among the gametes is eliminated, because crossing over is the sole source of diversity introduced during meiosis."}, {"label": "B", "text": "Only genes located on the same chromosome still appear in new combinations, while genes on different chromosomes are now inherited together as a single unit."}, {"label": "C", "text": "Variation from the random metaphase-I orientation of the nonhomologous tetrads still produces up to 2^n gamete combinations, because independent assortment is a separate mechanism that does not require crossing over."}, {"label": "D", "text": "The 2^n possible chromosome arrangements at metaphase I are themselves lost, because tetrads can no longer assort independently once no chiasma forms."}]$op14$::jsonb, 'C', $ex14$This is a Biology question that falls under the content category 'Meiosis & Genetic Variability (BIO)'. The answer is C because independent assortment of homologous chromosomes at the metaphase plate is a second, mechanistically distinct source of meiotic variation that operates regardless of whether crossing over occurs. The text states that meiosis I creates diverse gametes "in two ways"—crossover events in prophase I and "the random assortment of tetrads on the metaphase plate"—and explicitly identifies random assortment as "the second mechanism that introduces variation into the gametes." It further notes that the 2^n alignment count "does not include the variability that was previously produced by crossing over," confirming the two sources are independent; therefore suppressing all crossover removes only the first source while the up-to-2^n combinations from random orientation persist. (Choice A) is wrong because it treats crossing over as the only source and ignores that random assortment of tetrads is described as a separate, second mechanism. (Choice B) reverses the actual relationship: independent assortment shuffles genes on different (nonhomologous) chromosomes, whereas genes on the same chromosome are the ones that tend to stay linked when crossover is absent. (Choice C) is correct because the random orientation of each tetrad—independent of the other tetrads—yields 2^n combinations whether or not a chiasma ever forms. (Choice D) is a partial truth: a chiasma helps hold homologs together for proper segregation, but its loss does not erase the independent orientation of separate tetrads that generates the 2^n combinations. This is a Scientific Reasoning and Problem Solving question because it requires predicting the outcome of an experimental manipulation by isolating one of two distinct mechanisms and reasoning about what the remaining mechanism still contributes.$ex14$, 'hard', '1C', $cc14$Meiosis & Genetic Variability (BIO)$cc14$, 'biology', 2, 150
  ) RETURNING id
)
INSERT INTO question_distractor_metadata (question_id, choice_label, distractor_category, archetype)
SELECT id, 'A', 'misconception', $a14A$treats crossing over as the only source of meiotic variation, ignoring independent assortment$a14A$ FROM q
UNION ALL SELECT id, 'B', 'reversed_relationship', $a14B$swaps which genes assort independently (different-chromosome) versus stay linked (same-chromosome)$a14B$ FROM q
UNION ALL SELECT id, 'D', 'partial_truth', $a14D$correctly notes a chiasma aids pairing/segregation but wrongly concludes its loss abolishes independent assortment$a14D$ FROM q;

-- Q15 [Crossing Over & Recombination | hard | Skill 2 | ans D]
WITH q AS (
  INSERT INTO questions (section, topic, subtopic, question_text, options, correct_answer, explanation, difficulty, foundation, content_category, discipline, cognitive_skill, estimated_time_seconds)
  VALUES (
    'bio_biochem', 'Reproduction', $sub15$Crossing Over & Recombination$sub15$, $qt15$A geneticist test-crosses a fly heterozygous at two loci, P and Q, to a homozygous recessive partner and recovers offspring of which 49.6% carry recombinant (nonparental) allele combinations. The geneticist wants to place P and Q on the existing chromosome map. What is the MOST defensible conclusion about the relationship between P and Q from this single test-cross result?$qt15$, $op15$[{"label": "A", "text": "P and Q are extremely tightly linked, because the high recombinant percentage signals a very short physical distance between them."}, {"label": "B", "text": "P and Q lie exactly 50 cM apart, a precise distance that can be added directly to neighboring map intervals."}, {"label": "C", "text": "P and Q must be undergoing multiple crossovers, which is why the recombinant fraction has been driven above one half."}, {"label": "D", "text": "P and Q are sorting as if unlinked, so they are either far apart on one chromosome or on different chromosomes, and their true distance cannot be resolved."}]$op15$::jsonb, 'D', $ex15$This is a Biology question that falls under the content category 'Meiosis & Genetic Variability (BIO)'. The answer is D because a recombination frequency of roughly 50% is the maximum value the measure can reach, at which point the two loci assort exactly as independently assorting (unlinked) genes do, leaving their physical relationship ambiguous. The text states that genes range from linking perfectly (recombination frequency = 0) to unlinking perfectly (recombination frequency = 0.5) "when genes are on different chromosomes or genes separate very far apart on the same chromosome," and that "as the genetic distances approached 0.50, his predictions became less accurate because it was not clear whether the genes were very far apart on the same or on different chromosomes." A 0.5 frequency means 50% recombinants and 50% parental types, so every allele combination appears equally — the signature of independent assortment — and the underlying distance cannot be read beyond this ceiling. (Choice A) is reversed: the text says "as the distance between two genes increases, the probability of one or more crossovers between them increases," so a high recombinant percentage signals large distance or no linkage, not tight linkage. (Choice B) treats ~50% as a clean additive map distance, but the text warns that near 0.50 predictions "became less accurate" precisely because the same/different-chromosome question is unresolved, so 50 cM cannot be confidently added to other intervals. (Choice C) invokes multiple crossovers to push the value past one half, but a crossover frequency only ranges "between 0 percent and 50 percent," so it cannot exceed 50%. (Choice D) correctly recognizes that at ~50% recombinants the genes behave as though unlinked, making far-apart-same-chromosome and different-chromosome scenarios indistinguishable. This is a Scientific Reasoning and Problem Solving question because it requires interpreting an experimental test-cross datum against the known 50% recombination ceiling to judge which mapping conclusion is actually supportable.$ex15$, 'hard', '1C', $cc15$Meiosis & Genetic Variability (BIO)$cc15$, 'biology', 2, 160
  ) RETURNING id
)
