UNION ALL SELECT id, 'B', 'partial_truth', $a15B$Correctly converts frequency to cM but ignores that additive mapping predictions break down as frequency approaches 0.5$a15B$ FROM q
UNION ALL SELECT id, 'C', 'misconception', $a15C$Believes recombination frequency can exceed 50% when multiple crossovers occur between distant genes$a15C$ FROM q;

-- Q16 [Linkage & Independent Assortment | easy | Skill 1 | ans A]
WITH q AS (
  INSERT INTO questions (section, topic, subtopic, question_text, options, correct_answer, explanation, difficulty, foundation, content_category, discipline, cognitive_skill, estimated_time_seconds)
  VALUES (
    'bio_biochem', 'Reproduction', $sub16$Linkage & Independent Assortment$sub16$, $qt16$A human germ cell completing meiosis I produces gametes that carry many different combinations of maternally and paternally inherited chromosomes, far more than crossing over alone could explain. A student is asked to identify the single cellular event that serves as the physical basis of Mendel's law of independent assortment. Which event should the student name?$qt16$, $op16$[{"label": "A", "text": "The random orientation of each tetrad at the metaphase I plate, so that any maternal or paternal chromosome may face either pole independently of the other pairs."}, {"label": "B", "text": "The separation of sister chromatids during anaphase II, which delivers a single chromatid of each chromosome to each gamete."}, {"label": "C", "text": "The synapsis of homologous chromosomes during prophase I, which pairs the two homologs together into a tetrad."}, {"label": "D", "text": "The reciprocal crossing over between nonsister chromatids during prophase I, which exchanges segments between homologous chromosomes."}]$op16$::jsonb, 'A', $ex16$This is a Biology question that falls under the content category 'Meiosis & Genetic Variability (BIO)'. The answer is A because the physical basis of independent assortment is the random orientation of each homologous pair (tetrad) at the metaphase I plate. The text states that "the arrangement of the tetrads at the metaphase plate is random. Thus, any maternally inherited chromosome may face either pole... The orientation of each tetrad is independent of the orientation of the other 22 tetrads," and it explicitly notes that "the physical basis for the law of independent assortment also lies in meiosis I, in which the different homologous pairs line up in random orientations." Because each pair orients independently, a gamete "can contain any combination of paternal and maternal chromosomes," producing over 8 million combinations in humans even before crossing over. (Choice A) is correct: the independent, random orientation of tetrads at metaphase I is exactly the event the text names as the physical basis of independent assortment. (Choice B) is wrong because anaphase II separates sister chromatids in meiosis II to deliver single chromatids to gametes—this is the final step of segregation, not the basis of independent assortment. (Choice C) is wrong because synapsis only pairs homologs into tetrads during prophase I; it organizes pairing but does not randomize how the pairs face the poles. (Choice D) is wrong because crossing over is a separate, first source of genetic variation (recombination) that exchanges segments between nonsister chromatids, not the mechanism behind independent assortment. This is a Knowledge of Scientific Concepts and Principles question because it requires recalling the specific meiotic event that the textbook identifies as the physical basis of Mendel's law of independent assortment.$ex16$, 'easy', '1C', $cc16$Meiosis & Genetic Variability (BIO)$cc16$, 'biology', 1, 75
  ) RETURNING id
)
INSERT INTO question_distractor_metadata (question_id, choice_label, distractor_category, archetype)
