SELECT id, 'A', 'reversed_relationship', $a22A$Applies the meiosis II nondisjunction outcome (two normal gametes) to a meiosis I error$a22A$ FROM q
UNION ALL SELECT id, 'B', 'misconception', $a22B$Assumes chromosomes are re-duplicated during interkinesis/meiosis II$a22B$ FROM q
UNION ALL SELECT id, 'D', 'partial_truth', $a22D$Treats meiosis I nondisjunction as affecting only a single chromatid, sparing three gametes$a22D$ FROM q;

-- Q23 [Nondisjunction & Meiosis vs Mitosis | medium | Skill 2 | ans D]
WITH q AS (
  INSERT INTO questions (section, topic, subtopic, question_text, options, correct_answer, explanation, difficulty, foundation, content_category, discipline, cognitive_skill, estimated_time_seconds)
  VALUES (
    'bio_biochem', 'Reproduction', $sub23$Nondisjunction & Meiosis vs Mitosis$sub23$, $qt23$A geneticist tracks a single diploid spermatocyte (2n) through a complete, error-free meiosis and records the number of chromosome sets in each nucleus at the end of each nuclear division. She wants to identify which division first cuts the nucleus from two chromosome sets to one and to explain mechanistically why that drop occurs there. Which division is reductional, and what event accounts for it?$qt23$, $op23$[{"label": "A", "text": "Meiosis II, because separating sister chromatids is the step that lowers the genome copy number in each resulting nucleus"}, {"label": "B", "text": "Mitosis acting on this diploid cell, because distributing chromosomes between two daughter nuclei lowers the chromosome-set number"}, {"label": "C", "text": "The S phase preceding meiosis, because replicating each chromosome into two sister chromatids changes the chromosome-set number"}, {"label": "D", "text": "Meiosis I, because pulling homologous chromosomes (not sister chromatids) to opposite poles drops each nucleus from two chromosome sets to one"}]$op23$::jsonb, 'D', $ex23$This is a Biology question that falls under the content category 'Meiosis & Genetic Variability (BIO)'. The answer is D because the reduction in ploidy is defined by the separation of homologous chromosomes, which happens only in meiosis I. The text states that when the tetrad breaks up "with the homologous chromosomes moving to one pole or another, the ploidy level—the number of sets of chromosomes in each future nucleus—has been reduced from two to one. For this reason, meiosis I is referred to as a reductional division" (lines 13948-13951). Crucially, the drop in chromosome-set number tracks the partitioning of homologs, not the later separation of sister chromatids; meiosis II keeps "still one set of chromosomes" even though copy number falls (lines 13959-13960), and mitosis keeps "both the parent and daughter nuclei... at the same 'ploidy level'" (lines 13669-13671). (Choice A) is wrong because, although meiosis II does separate sister chromatids, the text explicitly says "Meiosis II is not a reduction division because... there is still one set of chromosomes, as there was at the end of meiosis I"—copy number falls but ploidy does not. (Choice B) is wrong because the text notes that in mitosis "both the parent and the daughter nuclei are at the same 'ploidy level'," so a mitotic division of a diploid cell yields diploid daughters and is never reductional. (Choice C) is wrong because S phase replicates "each chromosome... to produce two identical copies—sister chromatids," which doubles DNA content per chromosome without altering the number of chromosome sets, so it cannot be the reductional step. (Choice D) is correct because the move of homologous chromosomes to opposite poles is exactly the event the text ties to the two-to-one drop in ploidy that defines reductional division. This is a Scientific Reasoning and Problem Solving question because the student must distinguish chromosome-set number (ploidy) from DNA/copy number and trace a cell through successive divisions to determine where, and mechanistically why, ploidy is first halved rather than recalling a definition.$ex23$, 'medium', '1C', $cc23$Meiosis & Genetic Variability (BIO)$cc23$, 'biology', 2, 110
  ) RETURNING id
)
INSERT INTO question_distractor_metadata (question_id, choice_label, distractor_category, archetype)
