UNION ALL SELECT id, 'B', 'process_step_confusion', $a25B$Confusing meiosis II sister-chromatid alignment (individual kinetochores) with synaptonemal-complex-mediated homolog synapsis, placing a meiosis I event into metaphase II$a25B$ FROM q
UNION ALL SELECT id, 'C', 'partial_truth', $a25C$510-tempting trap that correctly notes crossing over is lost but wrongly assumes homolog segregation is independent of chiasmata$a25C$ FROM q;

